ords\";a:0:{}s:3:\"alt\";s:0:\"\";}}'),(216,69,'_wp_attached_file','2026/08/PalestraHumanidades.jpg'),(217,69,'_wp_attachment_metadata','a:6:{s:5:\"width\";i:991;s:6:\"height\";i:1599;s:4:\"file\";s:31:\"2026/08/PalestraHumanidades.jpg\";s:8:\"filesize\";i:74817;s:5:\"sizes\";a:5:{s:6:\"medium\";a:5:{s:4:\"file\";s:31:\"PalestraHumanidades-186x300.jpg\";s:5:\"width\";i:186;s:6:\"height\";i:300;s:9:\"mime-type\";s:10:\"image/jpeg\";s:8:\"filesize\";i:9088;}s:5:\"large\";a:5:{s:4:\"file\";s:32:\"PalestraHumanidades-635x1024.jpg\";s:5:\"width\";i:635;s:6:\"height\";i:1024;s:9:\"mime-type\";s:10:\"image/jpeg\";s:8:\"filesize\";i:49140;}s:9:\"thumbnail\";a:5:{s:4:\"file\";s:31:\"PalestraHumanidades-150x150.jpg\";s:5:\"width\";i:150;s:6:\"height\";i:150;s:9:\"mime-type\";s:10:\"image/jpeg\";s:8:\"filesize\";i:4500;}s:12:\"medium_large\";a:5:{s:4:\"file\";s:32:\"PalestraHumanidades-768x1239.jpg\";s:5:\"width\";i:768;s:6:\"height\";i:1239;s:9:\"mime-type\";s:10:\"image/jpeg\";s:8:\"filesize\";i:64615;}s:9:\"1536x1536\";a:5:{s:4:\"file\";s:32:\"PalestraHumanidades-952x1536.jpg\";s:5:\"width\";i:952;s:6:\"height\";i:1536;s:9:\"mime-type\";s:10:\"image/jpeg\";s:8:\"filesize\";i:87958;}}s:10:\"image_meta\";a:13:{s:8:\"aperture\";s:1:\"0\";s:6:\"credit\";s:0:\"\";s:6:\"camera\";s:0:\"\";s:7:\"caption\";s:0:\"\";s:17:\"created_timestamp\";s:1:\"0\";s:9:\"copyright\";s:0:\"\";s:12:\"focal_length\";s:1:\"0\";s:3:\"iso\";s:1:\"0\";s:13:\"shutter_speed\";s:1:\"0\";s:5:\"title\";s:0:\"\";s:11:\"orientation\";s:1:\"0\";s:8:\"keywords\";a:0:{}s:3:\"alt\";s:0:\"\";}}'),(219,15,'livro_ano','2023'),(220,15,'livro_paginas','180'),(221,15,'livro_editora','Editora dos Editores'),(222,17,'livro_ano','7ª edição · 2026'),(223,17,'livro_paginas','215'),(224,17,'livro_editora','Guanabara Koogan'),(225,19,'livro_ano','2001'),(226,19,'livro_paginas','147'),(227,19,'livro_editora','EdUerj'),(228,21,'livro_ano','2019'),(229,21,'livro_paginas','487'),(230,21,'livro_editora','Autografia'),(231,15,'livro_resenha_texto','Figuras públicas sempre tiveram seus feitos levados à população geral através da mídia, principalmente pelo potencial impacto na vida das pessoas por meio da participação em movimentos culturais, políticos, ou simplesmente por serem formadoras de opinião. Em \"Fogo & Cinzas: as incríveis histórias de bipolares famosos\" [1] o renomado psiquiatra Elie Cheniaux e a psicóloga Thiara Cruz trazem em 17 capítulos independentes a análise de histórias de figuras famosas sob a ótica da ciência da saúde mental, tendo como base comportamentos relatados, documentos oficiais, notícias e históricos médicos. Nesta obra, os autores assumem papel de “investigadores” e “historiadores”, buscando organizar os dados obtidos para relatar e enquadrar padrões comportamentais e de sintomas em determinada classificação diagnóstica. De leitura simples e fluida, o texto é acessível à população leiga na área, sem abrir mão do rigor científico na análise psicopatológica realizada. Durante a leitura, diversos relatos lembram os de pessoas comuns e nos fazem enxergar que a manifestação da doença psiquiátrica não ocorre de forma “tão diferente” entre a pessoa “comum,’’ e o famoso. Explico: “tão diferente”, pois o que diverge não é a manifestação da doença em si, mas os meios para colocar em prática as ideias de grandeza/delírios e os gastos exagerados, que podem passar despercebidos a depender da disponibilidade de recursos do indivíduo. A exemplo disso, podemos dizer que provavelmente Santos-Dumont não construiria 22 dirigíveis ao longo de sua vida se não fosse um herdeiro bastante rico. Estudos tentam relacionar, de forma indireta, a presença de transtorno bipolar e a criatividade, inteligência e sucesso de alguns indivíduos. Entretanto, durante a obra percebe-se que muitos daqueles famosos, provavelmente o seriam da mesma forma com ou sem o diagnóstico. Em muitos dos casos, a posição de destaque já poderia anteriormente ser atribuída à origem familiar, pois eram compostas por pessoas famosas de Hollywood, como Carrie Fisher, da política como na família Kennedy, da realeza como George III e Maria I e em outros casos o acesso a recursos educacionais e estímulos no desenvolvimento ou a oportunidade de “sentar-se à mesa com a sociedade intelectual” de artistas, escritores, inventores, como Santos-Dumont frequentemente tinha. Um dos grandes méritos do Fogo & Cinzas é trazer personalidades nascidas em diferentes épocas: desde o Rei George III em 1738, até Kanye West em 1977, mostrando que as manifestações psiquiátricas do transtorno eram semelhantes em todas as épocas. Contudo, também observamos que a forma como eram interpretadas e tratadas era diferente. No passado, maior ênfase era dada a diagnósticos diferenciais com condições clínicas, como porfiria, e terapêuticas de cunho moral, tratamentos purgativos e sangrias. Observamos a evolução da psiquiatria com o surgimento de medicações como o lítio e tratamentos como eletroconvulsoterapia, marcos importantes com grande impacto no desfecho do transtorno. Nota-se também a evolução dos sistemas classificatórios diagnósticos, sendo que muitos famosos receberam diagnóstico de psicose maníaco-depressiva, que possui algumas diferenças conceituais em comparação ao transtorno bipolar. Outro grande mérito da obra é a contribuição para a redução do estigma sobre o transtorno. Carrie Fisher, por exemplo, tornou-se ativista em prol da saúde mental, e tendo sido submetida à eletroconvulsoterapia, falou publicamente sobre essa forma de tratamento, buscando reduzir os preconceitos sobre o tema. Já Patrick Kennedy foi um grande apoiador de um projeto (depois tornado lei) que obrigava seguradoras de saúde a ampliarem a cobertura de tratamentos psiquiátricos. Por sua vez, o comediante Stephen Fry, que só aceitou iniciar tratamento dezessete anos após seu diagnóstico, hoje é presidente de uma instituição de caridade destinada a pessoas que sofrem de transtornos mentais. A psicóloga Kay Jamison, que sofre de transtorno bipolar, é coautora de um dos livros mais importantes sobre o assunto. Muitos famosos utilizaram de sua notoriedade para trazer maior visibilidade ao tema, contribuindo para a redução da psicofobia, mostrando a importância do tratamento e da necessidade dos sistemas de saúde olharem para o tema com maior atenção. Nesta obra, de maneira brilhante, Cheniaux e Thiara Cruz suscitam o debate sobre a possível relação entre o transtorno afetivo bipolar e uma maior criatividade, traçam um panorama histórico da classificação e tratamentos da comorbidade e mostram os avanços assistenciais e a visibilidade trazida pelas figuras da obra ao longo dos anos. O texto de fácil compreensão consegue acessar desde o leigo até o especialista em saúde mental. É uma obra que permite àqueles não familizarizados com o tema compreender características do adoecimento psíquico. Portanto, a popularização desta obra contribui de forma relavante para a redução da psicofobia.'),(232,15,'livro_resenha_autores','Caio Silveira de Caro | é médico generalista graduado pela Universidade Regional de Blumenau (2015-2021).- Pós Graduado (NÃO ESPECIALISTA) em Psiquiatria na Clínica Médica e Cirúrgica no pela Faculdade Israelita de ciências da Saúde Albert Einstein. - Realiza atualmente especialização em Psiquiatria no Hospital Heidelberg(Curitiba/PR). - Atuou como Médico Clínico no Serviço de Avaliação em Saúde mental(SAS), da Prefeitura Municipal de Blumenau.\nKarla de Souza | é médica Psiquiatra\nJéssica Lovcke | é médica graduada em Medicina pela Universidade do Oeste de Santa Catarina - UNOESC (2013 - 2018), possui curso de especialização em atenção básica em saúde pela Universidade Federal de Santa Catarina (2019 - 2020), especialização pelo programa de formação em psiquiatria acreditado pela ABP no hospital Heidelberg no município de Curitiba/PR (2023 - 2026) e pós graduação em psiquiatria forense pelo IPq-USP (2025 - 2026)\nGabriela de Almeida | é médica formada pelo Centro Universitário Ingá (2018). Tem experiência no atendimento Clínico Geral e Urgência na UPA e UBS de Dourados.\nDaniel Guadagnin | é dentista graduado em Odontologia pela Universidade Positivo(2012) e possui graduação em Medicina pela FACULDADE EVANGELICA MACKENZIE DO PARANA(2022). Tem experiência na área de Medicina\nMariana Sampaio Ferelli | é médica graduada em Medicina pela Universidad Advenstista del Plata(2018). Atualmente é Especializando da Clínica Heidelberg. Tem experiência na área de Medicina, com ênfase em Psiquiatria'),(233,21,'livro_subtitulo','Seus filmes são mesmo autobiográficos?'),(234,15,'livro_subtitulo','AS INCRÍVEIS HISTÓRIAS DE BIPOLARES FAMOSOS'),(235,70,'_wp_attached_file','2026/08/Livro-O-ANTIFACEBOOK-2.jpg'),(236,70,'_wp_attachment_metadata','a:6:{s:5:\"width\";i:188;s:6:\"height\";i:268;s:4:\"file\";s:34:\"2026/08/Livro-O-ANTIFACEBOOK-2.jpg\";s:8:\"filesize\";i:9081;s:5:\"sizes\";a:1:{s:9:\"thumbnail\";a:5:{s:4:\"file\";s:34:\"Livro-O-ANTIFACEBOOK-2-150x150.jpg\";s:5:\"width\";i:150;s:6:\"height\";i:150;s:9:\"mime-type\";s:10:\"image/jpeg\";s:8:\"filesize\";i:6544;}}s:10:\"image_meta\";a:13:{s:8:\"aperture\";s:1:\"0\";s:6:\"credit\";s:0:\"\";s:6:\"camera\";s:0:\"\";s:7:\"caption\";s:0:\"\";s:17:\"created_timestamp\";s:1:\"0\";s:9:\"copyright\";s:0:\"\";s:12:\"focal_length\";s:1:\"0\";s:3:\"iso\";s:1:\"0\";s:13:\"shutter_speed\";s:1:\"0\";s:5:\"title\";s:0:\"\";s:11:\"orientation\";s:1:\"0\";s:8:\"keywords\";a:0:{}s:3:\"alt\";s:0:\"\";}}'),(237,71,'_wp_attached_file','2026/08/Livro-Fogo-e-Cinzas-2.jpg'),(238,71,'_wp_attachment_metadata','a:6:{s:5:\"width\";i:905;s:6:\"height\";i:1280;s:4:\"file\";s:33:\"2026/08/Livro-Fogo-e-Cinzas-2.jpg\";s:8:\"filesize\";i:146287;s:5:\"sizes\";a:4:{s:6:\"medium\";a:5:{s:4:\"file\";s:33:\"Livro-Fogo-e-Cinzas-2-212x300.jpg\";s:5:\"width\";i:212;s:6:\"height\";i:300;s:9:\"mime-type\";s:10:\"image/jpeg\";s:8:\"filesize\";i:17455;}s:5:\"large\";a:5:{s:4:\"file\";s:34:\"Livro-Fogo-e-Cinzas-2-724x1024.jpg\";s:5:\"width\";i:724;s:6:\"h