;i:300;s:9:\"mime-type\";s:10:\"image/jpeg\";s:8:\"filesize\";i:14634;}s:5:\"large\";a:5:{s:4:\"file\";s:48:\"livro-manual-psicopatologia-capa-2-629x1024.jpeg\";s:5:\"width\";i:629;s:6:\"height\";i:1024;s:9:\"mime-type\";s:10:\"image/jpeg\";s:8:\"filesize\";i:97221;}s:9:\"thumbnail\";a:5:{s:4:\"file\";s:47:\"livro-manual-psicopatologia-capa-2-150x150.jpeg\";s:5:\"width\";i:150;s:6:\"height\";i:150;s:9:\"mime-type\";s:10:\"image/jpeg\";s:8:\"filesize\";i:7423;}s:12:\"medium_large\";a:5:{s:4:\"file\";s:48:\"livro-manual-psicopatologia-capa-2-768x1250.jpeg\";s:5:\"width\";i:768;s:6:\"height\";i:1250;s:9:\"mime-type\";s:10:\"image/jpeg\";s:8:\"filesize\";i:129863;}s:9:\"1536x1536\";a:5:{s:4:\"file\";s:48:\"livro-manual-psicopatologia-capa-2-944x1536.jpeg\";s:5:\"width\";i:944;s:6:\"height\";i:1536;s:9:\"mime-type\";s:10:\"image/jpeg\";s:8:\"filesize\";i:172537;}}s:10:\"image_meta\";a:13:{s:8:\"aperture\";s:1:\"0\";s:6:\"credit\";s:0:\"\";s:6:\"camera\";s:0:\"\";s:7:\"caption\";s:0:\"\";s:17:\"created_timestamp\";s:1:\"0\";s:9:\"copyright\";s:0:\"\";s:12:\"focal_length\";s:1:\"0\";s:3:\"iso\";s:1:\"0\";s:13:\"shutter_speed\";s:1:\"0\";s:5:\"title\";s:0:\"\";s:11:\"orientation\";s:1:\"0\";s:8:\"keywords\";a:0:{}s:3:\"alt\";s:0:\"\";}}'),(332,116,'_wp_attached_file','2026/08/artigo-imagem-padrao-2.jpg'),(333,116,'_wp_attachment_metadata','a:6:{s:5:\"width\";i:290;s:6:\"height\";i:222;s:4:\"file\";s:34:\"2026/08/artigo-imagem-padrao-2.jpg\";s:8:\"filesize\";i:29726;s:5:\"sizes\";a:1:{s:9:\"thumbnail\";a:5:{s:4:\"file\";s:34:\"artigo-imagem-padrao-2-150x150.jpg\";s:5:\"width\";i:150;s:6:\"height\";i:150;s:9:\"mime-type\";s:10:\"image/jpeg\";s:8:\"filesize\";i:8960;}}s:10:\"image_meta\";a:13:{s:8:\"aperture\";s:1:\"0\";s:6:\"credit\";s:0:\"\";s:6:\"camera\";s:0:\"\";s:7:\"caption\";s:0:\"\";s:17:\"created_timestamp\";s:1:\"0\";s:9:\"copyright\";s:0:\"\";s:12:\"focal_length\";s:1:\"0\";s:3:\"iso\";s:1:\"0\";s:13:\"shutter_speed\";s:1:\"0\";s:5:\"title\";s:0:\"\";s:11:\"orientation\";s:1:\"0\";s:8:\"keywords\";a:0:{}s:3:\"alt\";s:0:\"\";}}'),(334,11,'livro_capa_home','Livro O ANTIFACEBOOK 2.jpg'),(335,15,'livro_capa_home','Livro Fogo e Cinzas -2.jpg'),(336,17,'livro_capa_home','LivroMANUAL.jpg'),(337,19,'livro_capa_home','Livro SÍNDROME PRÉ-MENSTRUAL.jpg'),(338,21,'livro_capa_home','Livro WOODY ALLEN.jpg'),(339,17,'livro_prefacio3_nome','Miguel Chalub'),(340,17,'livro_prefacio3_cargo','Professor-associado da Faculdade de Medicina da Universidade Federal do Rio de Janeiro (FM/UFRJ)'),(341,17,'livro_prefacio3_extra','Professor adjunto da Faculdade de Ciências Médicas da Universidade do Estado do Rio de Janeiro (FCM/UERJ)'),(342,17,'livro_prefacio3_texto','Infelizmente livros científicos brasileiros, ainda que de qualidade, têm pouco tempo de vida. Ou a primeira edição fica sempre disponível pois não tem a necessária saída por falta de mercado adquirinte ou nunca mais são reeditados eis que não há interesse dos publicadores pelas mesmas razões. \"Dormem\" para sempre nas bibliotecas e nos \"sebos\". Mas, por sorte nossa, há exceções. Uma delas é o \"Manual de Psicopatologia\" de Elie Cheniaux Jr. que chega à - pasmem! - 5a. edição. Uma das razões para que fato tão inusitado aconteça, é sua importante originalidade além de ser uma excelente compêndio deste saber médico-psicológico. A Psicopatologia, particularmente a fenomenológica, andava meio esquecida e, o que é pior, deconsiderada pelas novas gerações de psiquiatras, psicólogos e outros profissionais de saúde mental. A ideia errônea é que se tratava de um conhecimento ultrapassado e que teria interesse apenas histórico mas não utilidade para a prática psiquiátrica, mormente aquela subsidiária da Psiquiatria Social e Comunitária. Mas não é assim. As doenças mentais, o sofrimento psíquico só podem ser entendidos a partir do estudo das funções mentais e de seus transtornos. Sem este conhecimento prévio e introdutório, as ações sobre a prevenção e recuperação da saúde mental bem como o tratamento de suas anomalias, passa a ser mero fazer assistencial muitas vezes eivado de desvios ideológicos e políticos. Falta a fundamentação psicopatológica para uma verdadeira e científica ação médico-psicológica. O Manual de Psicopatologia em comento é um pequeno mas completo tratado de Fenomenologia Psiquiátrica, saber médico indispensável para aqueles que querem fazer o diagnóstico seguro das doenças mentais e de suas variadas formas clínicas e expressões sintomáticas. Mas vai mais além e aí começa sua vibrante originalidade. Há uma correlação entre os atuais achados das neurociências e as doenças mentais, aproximação que é cada vez mais fecunda e que possivelmente provocará uma grande revolução no tratamento dos transtornos mentais. A neurobiologia se encontra com a Psicopatologia, fato inteiramente novo! Mas, como psicanalista, o autor nos dá mais. A fenomenologia \"clássica\" - e o adjetivo aí é um grande elogio para os que estudam a Psiquiatria de uma maneira rigorosa e a praticam de modo fundamentado - é cotejada com a doutrina psicanalítica e assim ficamos com uma tríplice visão: os fenômenos mentais anormais descritos de maneira rigorosa e colocados lado a lado com o contributo das neurociências e da psicanálise. Esta riqueza não é comum nos livros estrangeiros e nacionais de Psiquiatria e Psicopatologia e é de um valor inestimável para psiquiatras, psicólogos e psicanalistas bem como para outros interessados nos problemas da saúde mental. A presente edição além de trazer os acréscimos de edições anteriores como a discussão da nomenclatura em Psicopatologia traz dois novos temas de grande interesse prático: 1) um modelo de exame psíquico e súmula psicopatológica, de enorme valor para o exercício profissional pois procura uniformizar a transposição da teoria psicopatológica para a avaliação de um caso clínico concreto; 2) a relação das alterações psicopatológicas de acordo com as funções psíquicas, ajuda inestimável para uma melhor ordenação da perquirição clínica. Por todas estas razões o livro de Elie Cheniaux Jr. tornou-se uma obra indispensável para médicos e psicólogos pois é uma obra fundamental para o conhecimento e o exercício rigoroso da prática clínica médico-psiquiátrica e psicológica.'),(343,13,'livro_subtitulo','Conhecendo os Transtornos Mentais Através dos Filmes'),(344,19,'livro_subtitulo','Um ponto de encontro entre a psiquiatria e a ginecologia');
