--
-- Table structure for table `wp_posts`
--

DROP TABLE IF EXISTS `wp_posts`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `wp_posts` (
  `ID` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `post_author` bigint(20) unsigned NOT NULL DEFAULT 0,
  `post_date` datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
  `post_date_gmt` datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
  `post_content` longtext NOT NULL,
  `post_title` text NOT NULL,
  `post_excerpt` text NOT NULL,
  `post_status` varchar(20) NOT NULL DEFAULT 'publish',
  `comment_status` varchar(20) NOT NULL DEFAULT 'open',
  `ping_status` varchar(20) NOT NULL DEFAULT 'open',
  `post_password` varchar(255) NOT NULL DEFAULT '',
  `post_name` varchar(200) NOT NULL DEFAULT '',
  `to_ping` text NOT NULL,
  `pinged` text NOT NULL,
  `post_modified` datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
  `post_modified_gmt` datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
  `post_content_filtered` longtext NOT NULL,
  `post_parent` bigint(20) unsigned NOT NULL DEFAULT 0,
  `guid` varchar(255) NOT NULL DEFAULT '',
  `menu_order` int(11) NOT NULL DEFAULT 0,
  `post_type` varchar(20) NOT NULL DEFAULT 'post',
  `post_mime_type` varchar(100) NOT NULL DEFAULT '',
  `comment_count` bigint(20) NOT NULL DEFAULT 0,
  PRIMARY KEY (`ID`),
  KEY `post_name` (`post_name`(191)),
  KEY `type_status_date` (`post_type`,`post_status`,`post_date`,`ID`),
  KEY `post_parent` (`post_parent`),
  KEY `post_author` (`post_author`),
  KEY `type_status_author` (`post_type`,`post_status`,`post_author`)
) ENGINE=InnoDB AUTO_INCREMENT=117 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_520_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `wp_posts`
--

LOCK TABLES `wp_posts` WRITE;
/*!40000 ALTER TABLE `wp_posts` DISABLE KEYS */;
INSERT INTO `wp_posts` VALUES (1,1,'2026-08-08 15:32:21','2026-08-08 18:32:21','<!-- wp:paragraph -->\n<p>Boas-vindas ao WordPress. Esse é o seu primeiro post. Edite-o ou exclua-o, e então comece a escrever!</p>\n<!-- /wp:paragraph -->','Olá, mundo!','','publish','open','open','','ola-mundo','','','2026-08-08 15:32:21','2026-08-08 18:32:21','',0,'http://localhost/DrEliePetii/wordpress-site/?p=1',0,'post','',1),(2,1,'2026-08-08 15:32:21','2026-08-08 18:32:21','<!-- wp:paragraph -->\n<p>Esta é uma página de exemplo. É diferente de um post no blog porque ela permanecerá em um lugar e aparecerá na navegação do seu site na maioria dos temas. Muitas pessoas começam com uma página que as apresenta a possíveis visitantes do site. Ela pode dizer algo assim:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:quote -->\n<blockquote class=\"wp-block-quote\">\n<!-- wp:paragraph -->\n<p>Olá! Eu sou um mensageiro de bicicleta durante o dia, ator aspirante à noite, e este é o meu site. Eu moro em São Paulo, tenho um grande cachorro chamado Rex e gosto de tomar caipirinha (e banhos de chuva).</p>\n<!-- /wp:paragraph -->\n</blockquote>\n<!-- /wp:quote -->\n\n<!-- wp:paragraph -->\n<p>...ou alguma coisa assim:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:quote -->\n<blockquote class=\"wp-block-quote\">\n<!-- wp:paragraph -->\n<p>A Companhia de Miniaturas XYZ foi fundada em 1971, e desde então tem fornecido miniaturas de qualidade ao público. Localizada na cidade de Itu, a XYZ emprega mais de 2.000 pessoas e faz coisas grandiosas para a comunidade da cidade.</p>\n<!-- /wp:paragraph -->\n</blockquote>\n<!-- /wp:quote -->\n\n<!-- wp:paragraph -->\n<p>Como um novo usuário do WordPress, você deveria ir ao <a href=\"http://localhost/DrEliePetii/wordpress-site/wp-admin/\">painel</a> para excluir essa página e criar novas páginas para o seu conteúdo. Divirta-se!</p>\n<!-- /wp:paragraph -->','Página de exemplo','','publish','closed','open','','pagina-exemplo','','','2026-08-08 15:32:21','2026-08-08 18:32:21','',0,'http://localhost/DrEliePetii/wordpress-site/?page_id=2',0,'page','',0),(3,1,'2026-08-08 15:32:21','2026-08-08 18:32:21','<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Quem somos</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Texto sugerido: </strong>O endereço do nosso site é: http://localhost/DrEliePetii/wordpress-site.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Comentários</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Texto sugerido: </strong>Quando os visitantes deixam comentários no site, coletamos os dados mostrados no formulário de comentários, além do endereço de IP e de dados do navegador do visitante, para auxiliar na detecção de spam.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>Uma sequência anonimizada de caracteres criada a partir do seu e-mail (também chamada de hash) poderá ser enviada para o Gravatar para verificar se você usa o serviço. A política de privacidade do Gravatar está disponível aqui: https://automattic.com/privacy/. Depois da aprovação do seu comentário, a foto do seu perfil fica visível publicamente junto de seu comentário.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Mídia</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Texto sugerido: </strong>Se você envia imagens para o site, evite enviar as que contenham dados de localização incorporados (EXIF GPS). Visitantes podem baixar estas imagens do site e extrair delas seus dados de localização.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Cookies</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Texto sugerido: </strong>Ao deixar um comentário no site, você poderá optar por salvar seu nome, e-mail e site nos cookies. Isso visa seu conforto, assim você não precisará preencher seus  dados novamente quando fizer outro comentário. Estes cookies duram um ano.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>Se você tem uma conta e acessa este site, um cookie temporário será criado para determinar se seu navegador aceita cookies. Ele não contém nenhum dado pessoal e será descartado quando você fechar seu navegador.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>Quando você acessa sua conta no site, também criamos vários cookies para salvar os dados da sua conta e suas escolhas de exibição de tela. Cookies de login são mantidos por dois dias e cookies de opções de tela por um ano. Se você selecionar &quot;Lembrar-me&quot;, seu acesso será mantido por duas semanas. Se você se desconectar da sua conta, os cookies de login serão removidos.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>Se você editar ou publicar um artigo, um cookie adicional será salvo no seu navegador. Este cookie não inclui nenhum dado pessoal e simplesmente indica o ID do post referente ao artigo que você acabou de editar. Ele expira depois de 1 dia.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Mídia incorporada de outros sites</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Texto sugerido: </strong>Artigos neste site podem incluir conteúdo incorporado como, por exemplo, vídeos, imagens, artigos, etc. Conteúdos incorporados de outros sites se comportam exatamente da mesma forma como se o visitante estivesse visitando o outro site.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>Estes sites podem coletar dados sobre você, usar cookies, incorporar rastreamento adicional de terceiros e monitorar sua interação com este conteúdo incorporado, incluindo sua interação com o conteúdo incorporado se você tem uma conta e está conectado com o site.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Com quem compartilhamos seus dados</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Texto sugerido: </strong>Se você solicitar uma redefinição de senha, seu endereço de IP será incluído no e-mail de redefinição de senha.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Por quanto tempo mantemos os seus dados</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Texto sugerido: </strong>Se você deixar um comentário, o comentário e os seus metadados são conservados indefinidamente. Fazemos isso para que seja possível reconhecer e aprovar automaticamente qualquer comentário posterior ao invés de retê-lo para moderação.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>Para usuários que se registram no nosso site (se houver), também guardamos as informações pessoais que fornecem no seu perfil de usuário. Todos os usuários podem ver, editar ou excluir suas informações pessoais a qualquer momento (só não é possível alterar o seu username). Os administradores de sites também podem ver e editar estas informações.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Quais os seus direitos sobre seus dados</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Texto sugerido: </strong>Se você tiver uma conta neste site ou se tiver deixado comentários, pode solicitar um arquivo exportado dos dados pessoais que mantemos sobre você, inclusive quaisquer dados que nos tenha fornecido. Também pode solicitar que removamos qualquer dado pessoal que mantemos sobre você. Isto não inclui nenhuns dados que somos obrigados a manter para propósitos administrativos, legais ou de segurança.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Para onde seus dados são enviados</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Texto sugerido: </strong>Comentários de visitantes podem ser marcados por um serviço automático de detecção de spam.</p>\n<!-- /wp:paragraph -->\n','Política de privacidade','','draft','closed','open','','politica-de-privacidade','','','2026-08-08 15:32:21','2026-08-08 18:32:21','',0,'http://localhost/DrEliePetii/wordpress-site/?page_id=3',0,'page','',0),(4,0,'2026-08-08 15:32:24','2026-08-08 18:32:24','<!-- wp:page-list /-->','Navegação','','publish','closed','closed','','navigation','','','2026-08-08 15:32:24','2026-08-08 18:32:24','',0,'http://localhost/DrEliePetii/wordpress-site/index.php/2026/08/08/navigation/',0,'wp_navigation','',0),(5,0,'2026-08-08 15:32:41','2026-08-08 18:32:41','<div class=\"reveal\">\n<div class=\"prose\">\n<ul class=\"list-disc list-inside space-y-2\">\n<li>Professor Titular de psiquiatria da Faculdade de Ciências Médicas da Universidade do Estado do Rio de Janeiro (FCM-UERJ)<br/><a href=\"https://fcm.uerj.br/dem\" target=\"_blank\">https://fcm.uerj.br/dem</a></li>\n<li>Médico graduado pela Universidade do Estado do Rio de Janeiro, especialista em psiquiatria pela Associação Brasileira de Psiquiatria (ABP) <br/><a href=\"https://www.abp.org.br/lista-de-psiquiatras\" target=\"_blank\">https://www.abp.org.br/lista-de-psiquiatras</a></li>\n<li>RQE: 9397 (CREMERJ) Especialista em Psiquiatria <br/><a href=\"https://portal.cremerj.org.br/busca-medicos\" target=\"_blank\">https://portal.cremerj.org.br/busca-medicos</a></li>\n<li>Ex-professor do Programa de Pós-graduação em Psiquiatria e Saúde Mental da Universidade Federal do Rio de Janeiro (PROPSAM-IPUB-UFRJ) <a href=\"https://propsam.ipub.ufrj.br\" target=\"_blank\">https://propsam.ipub.ufrj.br</a></li>\n<li>Coordenador do Laboratório de Pesquisa em Transtorno Bipolar (BiPoLaB), vinculado ao Programa de Pós-Graduação em Ciências Médicas da UERJ <a href=\"https://www.pgcm.uerj.br/administracao/src/view/action/SiteAction.php\" target=\"_blank\">https://www.pgcm.uerj.br/administracao/src/view/action/SiteAction.php</a></li>\n<li>Membro titular da Academia de Medicina do Rio de Janeiro (AMRJ), cadeira 56 <a href=\"https://amrj.org.br/membro-amrj/elie-cheniaux-junior/\" target=\"_blank\">https://amrj.org.br/membro-amrj/elie-cheniaux-junior/</a></li>\n<li>Membro titular da Academia Brasileira de Médicos Escritores (ABRAMES), cadeira 30 <a href=\"https://www.abrames.com.br/2022/01/cadeira-30.html\" target=\"_blank\">https://www.abrames.com.br/2022/01/cadeira-30.html</a></li>\n<li>Médico (aposentado) do Instituto de Psiquiatria da UFRJ (IPUB) <a href=\"https://www.ipub.ufrj.br/\" target=\"_blank\">https://www.ipub.ufrj.br/</a></li>\n<li>Mestre e doutor em psiquiatria e saúde mental (PROPSAM-IPUB-UFRJ)</li>\n<li>Com pós-doutorado pela COPPE/UFRJ &amp; PUC-Rio</li>\n<li>Psicanalista, membro licenciado da Sociedade Psicanalítica do Rio de Janeiro (SPRJ) <a href=\"https://sprj.org.br/site/\" target=\"_blank\">https://sprj.org.br/site/</a></li>\n</ul>\n</div>\n</div>\n','Biografia','','publish','closed','closed','','biografia','','','2026-08-08 15:32:41','2026-08-08 18:32:41','',0,'http://localhost/DrEliePetii/wordpress-site/index.php/biografia/',0,'page','',0),(6,0,'2026-08-08 15:32:41','2026-08-08 18:32:41','\n<!-- Accordion sections -->\n<div class=\"reveal\">\n<iframe height=\"700px\" src=\"https://lattes.cnpq.br/4838737347351092\" style=\"border:1px solid #e5e7eb; border-radius:6px;\" width=\"100%\">\n</iframe>\n</div><!-- end accordion -->\n<!-- Lattes CTA -->\n<div class=\"mt-10 bg-white rounded shadow p-8 text-center reveal\">\n<div class=\"text-4xl mb-4\">🎓</div>\n<h3 class=\"text-xl font-bold mb-2\" style=\"color:var(--navy)\">Currículo Lattes</h3>\n<p class=\"text-gray-400 text-sm mb-6\">Para acessar o currículo  e atualizado na plataforma CNPq, clique no botão abaixo.</p>\n<a class=\"inline-block px-8 py-3 rounded font-bold text-sm uppercase tracking-wide transition-transform hover:-translate-y-1\" href=\"https://lattes.cnpq.br/4838737347351092\" style=\"background:var(--navy);color:white\" target=\"_blank\">Acessar Lattes CNPq →</a>\n</div>\n','Currículo Lattes','','publish','closed','closed','','curriculo','','','2026-08-08 15:32:41','2026-08-08 18:32:41','',0,'http://localhost/DrEliePetii/wordpress-site/index.php/curriculo/',0,'page','',0),(7,0,'2026-08-08 15:32:41','2026-08-08 18:32:41','\n<div>\n<!-- Speech text -->\n<div>\n<!-- Meta card -->\n<div class=\"speech-meta mb-8 reveal\">\n<div class=\"grid sm:grid-cols-3 gap-6 text-sm\">\n<div><div class=\"text-blue-300 text-xs font-bold uppercase tracking-widest mb-1\">Data</div><div class=\"font-bold\">Julho de 2024</div></div>\n<div><div class=\"text-blue-300 text-xs font-bold uppercase tracking-widest mb-1\">Local</div><div class=\"font-bold\">Sede da AMRJ, Rio de Janeiro</div></div>\n<div><div class=\"text-blue-300 text-xs font-bold uppercase tracking-widest mb-1\">Cadeira</div><div class=\"font-bold\">Nº 56 — Patrono: Dr. José de Paula Lopes Pontes</div></div>\n</div>\n</div>\n<!-- Speech body -->\n<article class=\"bg-white rounded shadow-sm px-8 py-10 reveal\">\n<div class=\"speech-body\">\n<div class=\"my-8\">\n<iframe height=\"700px\" src=\"https://www.eliecheniaux.com/_files/ugd/8a0ecd_64a31554f015454994c770c0d0a5dc43.pdf#toolbar=0\" style=\"border:1px solid #e5e7eb; border-radius:6px;\" width=\"100%\">\n              &lt;p&gt;Seu navegador não suporta exibição de PDF.&lt;/p&gt;\n            </iframe>\n</div>\n</div>\n</article>\n<!-- Download CTA -->\n<div class=\"mt-6 flex gap-4 flex-wrap reveal\">\n</div>\n</div>\n</div>\n','Discurso de Posse na AMRJ','','publish','closed','closed','','discurso','','','2026-08-08 15:32:41','2026-08-08 18:32:41','',0,'http://localhost/DrEliePetii/wordpress-site/index.php/discurso/',0,'page','',0),(8,0,'2026-08-08 15:32:41','2026-08-08 18:32:41','','Memorial','','publish','closed','closed','','memorial','','','2026-08-08 15:32:41','2026-08-08 18:32:41','',0,'http://localhost/DrEliePetii/wordpress-site/index.php/memorial/',0,'page','',0),(9,0,'2026-08-08 15:32:41','2026-08-08 18:32:41','\n<p>    O Laboratório de Pesquisa sobre o Transtorno Bipolar, o BiPoLaB, foi criado, em 2002, no Instituto de Psiquiatria da UFRJ, onde era vinculado ao Programa de Pós-Graduação em Psiquiatria e Saúde Mental (PROPSAM). Atualmente, está associado ao Programa de Pós-Graduação em Ciências Médicas (PGCM) da UERJ. Ele é coordenado pelos professores Elie Cheniaux e Estevão Scotti-Muzzi, que orientam ou supervisionam alunos de mestrado, doutorado, residência médica, especialização e iniciação científica. O BiPoLaB realiza estudos clínicos no ambulatório de psiquiatria do Hospital Universitário Pedro Ernesto (HUPE), nas sextas pela manhã, desde 2024.</p>\n<!-- Lattes CTA -->\n<div class=\"mt-10 bg-white rounded shadow p-8 text-center reveal\">\n</div>\n','Sobre o BiPoLaB','','publish','closed','closed','','bipolab','','','2026-08-08 15:32:41','2026-08-08 18:32:41','',0,'http://localhost/DrEliePetii/wordpress-site/index.php/bipolab/',0,'page','',0),(10,0,'2026-08-08 15:32:41','2026-08-08 18:32:41','','Encontros Especiais','','publish','closed','closed','','encontros','','','2026-08-08 15:32:41','2026-08-08 18:32:41','',0,'http://localhost/DrEliePetii/wordpress-site/index.php/encontros/',0,'page','',0),(11,0,'2026-08-08 15:32:41','2026-08-08 18:32:41','<p>“O Antifacebook” apresenta 24 textos de humor, num formato de crônica, curtos e escritos em primeira pessoa. São narrados fatos da vida do autor - que não necessariamente ocorreram -, mas a ênfase está menos nos relatos do que nos comentários, marcados por uma alta dose de ironia – especialmente autoironia – e, vez por outra, algum lirismo.</p>\n\n<p>Os principais temas abordados são: amor, sexo e casamento; felicidade, solidão e autoestima; futebol e Flamengo; religião; psiquiatria e psicanálise; e cinema.</p>\n\n<p>Nas crônicas, vários personagens são recorrentes, sendo citados, cada um deles, exatamente 117 vezes.</p>\n\n<p>Alguns são reais, como Zico, Chico Buarque, Nelson Rodrigues, Woody Allen, Alfred Hitchcock e Scarlett Johansson; e outros são fictícios, como o general Waldick (“o adorável vizinho do 505”), Deise (“a sedutora colega do ensino médio”), a mãe, a ex-esposa, Deus e, o mais fictício de todos, o “eu”.</p>','O Antifacebook','','publish','closed','closed','','antifacebook','','','2026-08-08 15:32:41','2026-08-08 18:32:41','',0,'http://localhost/DrEliePetii/wordpress-site/index.php/livros/antifacebook/',0,'livro','',0),(12,0,'2026-08-08 15:32:41','2026-08-08 18:32:41','','O Antifacebook - capa','','inherit','open','closed','','o-antifacebook-capa','','','2026-08-08 15:32:41','2026-08-08 18:32:41','',0,'http://localhost/DrEliePetii/wordpress-site/o-antifacebook-capa/',0,'attachment','image/jpeg',0),(13,0,'2026-08-08 15:32:42','2026-08-08 18:32:42','<p>Cinema e Loucura Neste livro surpreendente, os autores se propuseram a uma tarefa pioneira: usar personagens de filmes clássicos e modernos para auxiliar o leitor a compreender os mecanismos dos transtornos mentais, criando uma obra de interesse não apenas aos estudantes de saúde mental, mas a todos aqueles apaixonados por cinema.</p>','Cinema e Loucura','','publish','closed','closed','','cinema-loucura','','','2026-08-08 15:32:42','2026-08-08 18:32:42','',0,'http://localhost/DrEliePetii/wordpress-site/index.php/livros/cinema-loucura/',1,'livro','',0),(14,0,'2026-08-08 15:32:42','2026-08-08 18:32:42','','Cinema e Loucura - capa','','inherit','open','closed','','cinema-e-loucura-capa','','','2026-08-08 15:32:42','2026-08-08 18:32:42','',0,'http://localhost/DrEliePetii/wordpress-site/cinema-e-loucura-capa/',0,'attachment','image/jpeg',0),(15,0,'2026-08-08 15:32:43','2026-08-08 18:32:43','<p>FOGO & CINZAS: AS INCRÍVEIS HISTÓRIAS DE BIPOLARES FAMOSOS</p>\n\n<p>Apesar de representar uma condição clínica muito grave, o transtorno bipolar tem sido associado a possíveis vantagens compensatórias, especialmente a criatividade. Este livro discute as histórias de vida e do adoecimento mental de 17 indivíduos famosos que sofriam ou sofrem de transtorno bipolar, artistas em sua maioria. São eles: Alberto Santos-Dumont, Carrie Fisher, Edgar Allan Poe, Ernest Hemingway, George III da Inglaterra, Kanye West, Kay Jamison, Maria I de Portugal, Patrick Kennedy, Richard Dreyfuss, Robert Schumann, Stephen Fry, Sylvia Plath, Ulysses Guimarães, Vincent van Gogh, Virginia Woolf e Vivien Leigh..</p>\n\n<p>Embora a análise psiquiátrica de cada caso tenha sido feita de forma rigorosa do ponto de vista técnico, levando em consideração a psicopatologia clássica e os critérios diagnósticos mais modernos, o texto foi escrito em uma linguagem simples e acessível. Assim, esta obra é voltada não apenas para os estudantes e profissionais das áreas de psiquiatria e saúde mental, mas também para o público leigo em geral.</p>','Fogo & Cinzas','','publish','closed','closed','','fogo-cinzas','','','2026-08-08 15:32:43','2026-08-08 18:32:43','',0,'http://localhost/DrEliePetii/wordpress-site/index.php/livros/fogo-cinzas/',2,'livro','',0),(16,0,'2026-08-08 15:32:43','2026-08-08 18:32:43','','Fogo & Cinzas - capa','','inherit','open','closed','','fogo-cinzas-capa','','','2026-08-08 15:32:43','2026-08-08 18:32:43','',0,'http://localhost/DrEliePetii/wordpress-site/fogo-cinzas-capa/',0,'attachment','image/jpeg',0),(17,0,'2026-08-08 15:32:47','2026-08-08 18:32:47','<p>O Manual de Psicopatologia constitui uma proposta de síntese e revisão dos conceitos da psicopatologia descritiva. Após estudo dos principais autores, foi elaborada uma obra que representasse o somatório de todos os textos, privilegiando, nos casos de divergência, geralmente as proposições mais comuns. Cada função psíquica é estudada em um capítulo diferente, e cada capítulo apresenta sua definição, as alterações quantitativas e qualitativas (com diversos exemplos clínicos), a técnica de exame e sua relação com os principais transtornos e síndromes mentais. Também está incluída uma discussão sobre as descobertas das neurociências e as formulações teóricas da psicanálise relacionadas àquela função psíquica. O livro conta ainda com capítulos sobre os conceitos básicos da psicopatologia, a entrevista psiquiátrica e as principais síndromes psiquiátricas. Além disso, traz 13 apêndices, sendo sete novos, que abordam, além das alterações psicopatológicas e do exame psíquico, alguns temas psiquiátricos – como a antiga histeria, o transtorno bipolar e o transtorno esquizoafetivo –, a interface entre neurociência e psicanálise e a relação do cinema com a psicopatologia e a psiquiatria. Com prefácio assinado pelos professores Miguel Chalub, Antonio Egidio Nardi e Humberto Corrêa, esta sétima edição é, entre todas, a que apresenta a mais ampla revisão do texto.</p>','Manual de Psicopatologia','','publish','closed','closed','','manual-psicopatologia','','','2026-08-08 15:32:47','2026-08-08 18:32:47','',0,'http://localhost/DrEliePetii/wordpress-site/index.php/livros/manual-psicopatologia/',3,'livro','',0),(18,0,'2026-08-08 15:32:47','2026-08-08 18:32:47','','Manual de Psicopatologia - capa','','inherit','open','closed','','manual-de-psicopatologia-capa','','','2026-08-08 15:32:47','2026-08-08 18:32:47','',0,'http://localhost/DrEliePetii/wordpress-site/manual-de-psicopatologia-capa/',0,'attachment','image/jpeg',0),(19,0,'2026-08-08 15:32:48','2026-08-08 18:32:48','<p>A síndrome pré-menstrual é um bom exemplo da interação, ainda pouco conhecida, do sistema endócrino com o sistema nervoso e o psiquismo; é um ponto de encontro entre a psiquiatria, a endocrinologia e a ginecologia. O seu estudo contribui para uma maior integração do conhecimento médico.</p>\n\n<p>A obra é baseada na tese de doutoramento do autor, intitulada “A Inclusão da Síndrome Pré-Menstrual entre os Transtornos Mentais”, defendida no Instituto de Psiquiatria da UFRJ em 1997, sob a orientação do prof. dr. Miguel Chalub (professor adjunto de psiquiatria da UERJ e UFRJ).</p>','Síndrome Pré-Menstrual','','publish','closed','closed','','sindrome-pre-menstrual','','','2026-08-08 15:32:48','2026-08-08 18:32:48','',0,'http://localhost/DrEliePetii/wordpress-site/index.php/livros/sindrome-pre-menstrual/',4,'livro','',0),(20,0,'2026-08-08 15:32:48','2026-08-08 18:32:48','','Síndrome Pré-Menstrual - capa','','inherit','open','closed','','sindrome-pre-menstrual-capa','','','2026-08-08 15:32:48','2026-08-08 18:32:48','',0,'http://localhost/DrEliePetii/wordpress-site/sindrome-pre-menstrual-capa/',0,'attachment','image/jpeg',0),(21,0,'2026-08-08 15:32:49','2026-08-08 18:32:49','<p>Tão apaixonado por Woody Allen quanto por seu suposto alter ego das telas, Elie Cheniaux se debruça de forma minuciosa sobre a vida e obra do ator, diretor e roteirista para investigar até que ponto vão as semelhanças e diferenças. A decupagem criteriosa de seus 50 longas-metragens resultou em um trabalho revelador por parte do autor. (Marcelo Janot, crítico de cinema, O Globo)</p>','Woody Allen','','publish','closed','closed','','woody-allen','','','2026-08-08 15:32:49','2026-08-08 18:32:49','',0,'http://localhost/DrEliePetii/wordpress-site/index.php/livros/woody-allen/',5,'livro','',0),(22,0,'2026-08-08 15:32:49','2026-08-08 18:32:49','','Woody Allen - capa','','inherit','open','closed','','woody-allen-capa','','','2026-08-08 15:32:49','2026-08-08 18:32:49','',0,'http://localhost/DrEliePetii/wordpress-site/woody-allen-capa/',0,'attachment','image/jpeg',0),(23,0,'2026-08-08 15:32:50','2026-08-08 18:32:50','','Artigo - imagem padrão','','inherit','open','closed','','artigo-imagem-padrao','','','2026-08-08 15:32:50','2026-08-08 18:32:50','',0,'http://localhost/DrEliePetii/wordpress-site/artigo-imagem-padrao/',0,'attachment','image/jpeg',0),(24,0,'2026-08-08 15:32:51','2026-08-08 18:32:51','','Insight no TB','','publish','closed','closed','','insight-no-tb','','','2026-08-08 15:32:51','2026-08-08 18:32:51','',0,'http://localhost/DrEliePetii/wordpress-site/index.php/artigos-cientificos/insight-no-tb/',0,'artigo','',0),(25,0,'2026-08-08 15:32:51','2026-08-08 18: